class S3ClientConfig(TypedDict, total=False, closed=True):
    operation_interceptors: Iterable[Interceptor[Any, Any]]
    retry_max_attempts: int | None
    region: str | None
    use_fips: bool | None
    use_dual_stack: bool | None
    endpoint: str | None
    use_global_endpoint: bool | None
    credentials_provider: IdentityProvider[Credentials] | None
    force_path_style: bool | None
    use_arn_region: bool | None
    disable_multi_region_access_points: bool | None
    accelerate: bool | None
    disable_s3_express_session_auth: bool | None


class S3Client:
    """A client for the ``S3`` service.

    Args:
        http_handler: HTTP handler for sending requests. If not provided, creates a default handler.
        operation_interceptors: Interceptors that wrap every operation call. If not provided, defaults to an empty list.
        retry_max_attempts: Maximum number of times to retry a failed operation. Defaults to 3.
        region: The value of the ``AWS::Region`` endpoint parameter.
        use_fips: The value of the ``AWS::UseFIPS`` endpoint parameter.
        use_dual_stack: The value of the ``AWS::UseDualStack`` endpoint parameter.
        endpoint: The value of the ``SDK::Endpoint`` endpoint parameter.
        use_global_endpoint: The value of the ``AWS::S3::UseGlobalEndpoint`` endpoint parameter.
        credentials: AWS credentials for request signing.
        credentials_provider: Provider that resolves AWS credentials. Takes precedence over ``credentials``.
        force_path_style: Forces this client to use path-style addressing for buckets.
        use_arn_region: Enables this client to use an ARN's region when constructing an endpoint instead of the client's configured region.
        disable_multi_region_access_points: Disables this client's usage of Multi-Region Access Points.
        accelerate: Enables this client to use S3 Transfer Acceleration endpoints.
        disable_s3_express_session_auth: Disables this client's usage of Session Auth for S3Express       buckets and reverts to using conventional SigV4 for those.
    """

    def __init__(
        self,
        http_handler: BaseHandler | None = None,
        operation_interceptors: Iterable[Interceptor[Any, Any]] | None = None,
        retry_max_attempts: int | None = None,
        region: str | None = None,
        use_fips: bool | None = None,
        use_dual_stack: bool | None = None,
        endpoint: str | None = None,
        use_global_endpoint: bool | None = None,
        credentials: Credentials | None = None,
        credentials_provider: CredentialsProvider | None = None,
        force_path_style: bool | None = None,
        use_arn_region: bool | None = None,
        disable_multi_region_access_points: bool | None = None,
        accelerate: bool | None = None,
        disable_s3_express_session_auth: bool | None = None,
    ):
        self._client = (
            Client(http_handler)
            .wrap_with_middleware(lambda next: AuthMiddleware(next))
            .wrap_with_middleware(lambda next: ChecksumMiddleware(next))
        )
        if credentials is not None and credentials_provider is not None:
            warnings.warn(
                "Both credentials and credentials_provider given; provider takes precedence"
            )
        resolved_credentials_provider: IdentityProvider[Credentials] | None = (
            credentials_provider
        )
        if resolved_credentials_provider is None and credentials is not None:
            resolved_credentials_provider = StaticAwsCredentialsProvider(credentials)
        if resolved_credentials_provider is None and credentials is None:
            resolved_credentials_provider = default_aws_credentials_chain(
                Client(http_handler)
            )
